```csharp
using System;
using System.Data;
using System.Data.SqlClient;
using System.Xml;
public class CustomerRetriever
{
    public static string RetrieveCustomers(string connectionString)
    {
        string xmlResult = "";
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            string query = "SELECT * FROM customers";
            SqlCommand command = new SqlCommand(query, connection);
            connection.Open();
            using (XmlWriter writer = XmlWriter.Create(xmlResult))
            {
                writer.WriteStartElement("customers");
                using (SqlDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        writer.WriteStartElement("customer");
                        writer.WriteElementString("id", reader["id"].ToString());
                        writer.WriteElementString("name", reader["name"].ToString());
                        writer.WriteElementString("age", reader["age"].ToString());
                        writer.WriteEndElement(); // customer
                    }
                }
                writer.WriteEndElement(); // customers
            }
        }
        return xmlResult;
    }
}
```
