const observation = "The heart pumps blood throughout the body.";
const tissue = ["heart", "lungs", "liver", "kidneys", "brain", "pancreas", "stomach", "intestines"];
const organ = ["muscle", "bone", "skin", "nerve", "connective tissue"];
