$spreadsheet = "students_misbehavior.xlsx";
// load the spreadsheet file using PHPExcel library
require_once 'PHPExcel/Classes/PHPExcel.php';
$excel = PHPExcel_IOFactory::load($spreadsheet);
// get the active worksheet
$worksheet = $excel->getActiveSheet();
// define an array to store the consequences
$consequences = array();
// loop through each row in the worksheet
foreach ($worksheet->getRowIterator() as $row) {
    // get the cell values for each column
    $cellIterator = $row->getCellIterator();
    $cellIterator->setIterateOnlyExistingCells(FALSE);
    $cells = array();
    foreach ($cellIterator as $cell) {
        $cells[] = $cell->getValue();
    }
    // extract the values for each column
    $name = $cells[0];
    $date = $cells[1];
    $type = $cells[2];
    $severity = $cells[3];
    $frequency = $cells[4];
    $past_behavior = $cells[5];
    $mitigating_circumstances = $cells[6];
    // determine the appropriate consequence based on the factors
    if ($severity == "high" && $frequency >= 3) {
        $consequence = "suspension";
    } elseif ($severity == "medium" && $frequency >= 2) {
        $consequence = "detention";
    } elseif ($severity == "low" && $frequency == 1) {
        $consequence = "warning";
    } elseif ($past_behavior == "good" && $mitigating_circumstances == "yes") {
        $consequence = "counseling";
    } else {
        $consequence = "no consequence";
    }
    // store the consequence for each student
    $consequences[$name] = $consequence;
}
// print the consequences for each student
