Sure, here's the updated Swift code that generates haiku poems that follow the new rules:
```
let line1 = ["Cherry blossoms bloom", "The mountain's shadow", "The first cold shower"]
let line2 = ["Winter's final exhale", "Reflects on the still pond", "Drips from the gutter"]
let line3 = ["The sun sets slowly", "As the world falls asleep", "Autumn leaves dancing"]
func randomHaiku() -> String {
    let rand1 = Int(arc4random_uniform(UInt32(line1.count)))
    let rand3 = Int(arc4random_uniform(UInt32(line3.count)))

    var rand2 = Int(arc4random_uniform(UInt32(line2.count)))
    while !rhyme(line1[rand1], line2[rand2]) {
        rand2 = Int(arc4random_uniform(UInt32(line2.count)))
    }

    var rand4 = Int(arc4random_uniform(UInt32(line2.count)))
    while !rhyme(line3[rand3], line2[rand4]) {
        rand4 = Int(arc4random_uniform(UInt32(line2.count)))
    }

    return "\(line1[rand1])\n\(line2[rand2])\n\(line3[rand3])"
}
func rhyme(_ word1: String, _ word2: String) -> Bool {
    let vowels: [Character] = ["a", "e", "i", "o", "u"]

    if word1.count < 2 || word2.count < 2 {
        return false
    }

    let word1End = word1.suffix(2)
    let word2End = word2.suffix(2)

    if word1End == word2End {
        return true
    }

    for char in word1End {
        if vowels.contains(char) {
            let index = word1End.firstIndex(of: char)!
            let newEnd = word1End.suffix(from: index)
            if newEnd == word2End {
                return true
            }
        }
    }

    return false
}
```
