% Load the video file
video = VideoReader('missile_footage.mp4');
% Initialize variables
previous_frame = readFrame(video);
previous_center = [0, 0];
previous_time = 0;
speed_history = [];
% Loop through all frames
while hasFrame(video)
    % Read the current frame
    current_frame = readFrame(video);

    % Convert to grayscale and apply edge detection
    current_gray = rgb2gray(current_frame);
    current_edges = edge(current_gray, 'canny');

    % Find the center of the missile in the current frame
    current_center = find_missile_center(current_edges);

    % Calculate the distance traveled by the missile
    distance = norm(current_center - previous_center);

    % Calculate the time elapsed since the previous frame
    current_time = video.CurrentTime;
    elapsed_time = current_time - previous_time;

    % Calculate the speed of the missile
    speed = distance / elapsed_time;
    speed_history(end+1) = speed;

    % Update variables for the next frame
    previous_frame = current_frame;
    previous_center = current_center;
    previous_time = current_time;
end
% Plot the speed history
plot(speed_history);
xlabel('Frame number');
ylabel('Speed (m/s)');
title('Missile speed over time');
% Function to find the center of the missile in a given frame
function center = find_missile_center(edges)
    % Find the connected components in the edge map
    [labels, num_labels] = bwlabel(edges);

    % Initialize variables
    max_area = 0;
    center = [0, 0];

    % Loop through all connected components
    for i = 1:num_labels
        % Find the bounding box of the current component
        [row, col] = find(labels == i);
        bbox = [min(col), min(row), max(col)-min(col), max(row)-min(row)];

        % Calculate the area of the bounding box
        area = bbox(3) * bbox(4);

        % If the area is larger than the previous maximum, update the center
        if area > max_area
            center = [bbox(1)+bbox(3)/2, bbox(2)+bbox(4)/2];
            max_area = area;
        end
    end
end
```
