    private static Map<String, Map<String, Double>> calculateSimilarity(Map<String, Map<String, Double>> userRatings) {
        Map<String, Map<String, Double>> similarityMatrix = new HashMap<>();
        for (Map.Entry<String, Map<String, Double>> user1 : userRatings.entrySet()) {
            Map<String, Double> similarityScores = new HashMap<>();
            for (Map.Entry<String, Map<String, Double>> user2 : userRatings.entrySet()) {
                if (!user1.getKey().equals(user2.getKey())) {
                    double dotProduct = 0;
                    double norm1 = 0;
                    double norm2 = 0;
                    for (Map.Entry<String, Double> item : user1.getValue().entrySet()) {
