    rows, err := reader.ReadAll()
    if err != nil {
        panic(err)
    }
    // Print the first column of each row
    for _, row := range rows {
        fmt.Println(row[0])
    }
    // Add a new column to the CSV file
    for i, row := range rows {
        // Calculate the length of the first column's string value multiplied by 2
        length := len(row[0]) * 2
        // Add the new column to the row
        rows[i] = append(row, fmt.Sprintf("%d", length))
    }
    // Write the modified CSV file
    file, err = os.Create("data_with_length.csv")
    if err != nil {
        panic(err)
    }
    defer file.Close()
    writer := csv.NewWriter(file)
    writer.WriteAll(rows)
    if err := writer.Error(); err != nil {
